const baseColors = [
    "#2853BD",
    "#DA7C3A",
    "#4AA75E",
    "#1098FF",
    "#3852D6",
    "#D35D80"
];
export const getDefaultDatasetStyle = (dataSet) => {
    const newDataSet = Object.assign({}, dataSet);
    if (!newDataSet.backgroundColor) {
        newDataSet.backgroundColor = newDataSet.data.map((_, index) => baseColors[index % baseColors.length]);
    }
    newDataSet.hoverOffset = 4;
    return newDataSet;
};
